function buildEffectiveUnreadFilter(lastReadBySession) {
  return (message) => {
    if (Number(message.is_read) !== 0) {
      return false;
    }
    const lastReadAt = lastReadBySession.get(message.session_key);
    if (!lastReadAt) {
