const { PrismaClient } = require('/workspace/qq_bot/packages/persistence/generated/client');
const prisma = new PrismaClient();
(async()=>{
 const rows = await prisma.agentInboundMessage.findMany({
   where:{session_key:'qq:group:253631878', is_read:0, was_mentioned:1},
   orderBy:[{received_at:'desc'},{id:'desc'}],
   take:10,
   select:{id:true,received_at:true,message_timestamp:true,sender_id:true,sender_name:true,raw_body:true,body_for_agent:true,reply_to_id:true}
 });
 for (const r of rows) console.log(JSON.stringify(r,(_,v)=> typeof v==='bigint'?v.toString():v));
})().catch(e=>{console.error(e); process.exitCode=1}).finally(()=>prisma.$disconnect());
NODE","yield_time_ms":1000,"max_output_tokens":12000}

